const gpio=id=>{if(/^D\d+$/.test(id)){const n=+id.slice(1);return{net:id,digital:n,port:n<8?'D':'B',bit:n<8?n:n-8,pwm:[3,5,6,9,10,11].includes(n)};}if(/^A[0-7]$/.test(id)){const n=+id.slice(1);return{net:id,analog:n,...(n<6?{digital:14+n,port:'C',bit:n}:{analogOnly:true})};}if(id.startsWith('GND'))return{net:'GND',voltage:0};if(id.startsWith('RESET'))return{net:'RESET'};return{net:id,...(id==='5V'||id==='VCC'?{voltage:5}:id==='3.3V'?{voltage:3.3}:{})};};
