const megaDigital=[['E',0],['E',1],['E',4],['E',5],['G',5],['E',3],['H',3],['H',4],['H',5],['H',6],['B',4],['B',5],['B',6],['B',7],['J',1],['J',0],['H',1],['H',0],['D',3],['D',2],['D',1],['D',0],...Array.from({length:8},(_,bit)=>['A',bit]),...Array.from({length:8},(_,i)=>['C',7-i]),['D',7],['G',2],['G',1],['G',0],...Array.from({length:8},(_,i)=>['L',7-i]),['B',3],['B',2],['B',1],['B',0]];
const megaPin=(id,x,y,side)=>{const alias={SDA:'D20',SCL:'D21',IOREF:'5V'}[id],net=alias||id;let p={id,name:id,x,y,side,...gpio(id),net,...(id==='IOREF'?{voltage:5}:{})};if(/^D\d+$/.test(net)){const n=+net.slice(1),[port,bit]=megaDigital[n];p={...p,digital:n,port,bit,pwm:(n>=2&&n<=13)||(n>=44&&n<=46)};}else if(/^A\d+$/.test(net)){const n=+net.slice(1);p={...p,analogOnly:false,analog:n,digital:54+n,port:n<8?'F':'K',bit:n%8};}return p;};
const MEGA={id:'mega',name:'Arduino Mega 2560 R3',width:392,height:201.6,asset:'arduino-mega2560.svg',pins:[...UNO.pins.filter(p=>p.side==='top').map(p=>megaPin(p.id,p.x,p.y,p.side)),...Array.from({length:8},(_,i)=>megaPin('D'+(14+i),275+i*9.6,9.626457,'top')),...UNO.pins.filter(p=>p.side==='bottom'&&!/^A/.test(p.id)).map(p=>({...megaPin(p.id,p.x,p.y,p.side),...(p.connectable===false?{connectable:false}:{})})),...Array.from({length:16},(_,i)=>megaPin('A'+i,207.726614+(i<8?i*9.6:86.4+(i-8)*9.6),192.026457,'bottom')),...Array.from({length:32},(_,i)=>megaPin('D'+(22+i),i%2?381.5:371.9,33.626457+Math.floor(i/2)*9.6,'right')),...[['5V.1',371.9,24.026457],['5V.2',381.5,24.026457],['GND.3',371.9,187.226457],['GND.4',381.5,187.226457]].map(([id,x,y])=>({...megaPin(id,x,y,'right'),net:id.startsWith('5V')?'5V':'GND',voltage:id.startsWith('5V')?5:0}))],leds:{power:{x:251,y:54},D13:{x:125,y:45},TX:{x:110,y:58},RX:{x:110,y:67}},source:'https://docs.arduino.cc/resources/pinouts/A000067-full-pinout.pdf'};
